#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: the monitoring Stack's notification credentials on nc8kg1101 (#302).
# Writes each into its SOPS file with `sops set --value-stdin` and opens a PR.
# Never prints a value. Re-runnable: Enter keeps a value already in the repo.
#
# Test hook: WIZARD_NO_PR=1 writes the files in the current checkout and skips
# the branch, commit, push, PR and the live checks against the providers.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

REPO="asotbz/ops"
DIR="nc8kg1101/monitoring/alertmanager"
BRANCH="302-monitoring-secrets"
NO_PR="${WIZARD_NO_PR:-}"
PLACEHOLDER="placeholder"

ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

# current NAME: the value in $DIR/NAME.sops.txt, or nothing while it is the placeholder.
current() {
  local value
  value=$(sops -d "$DIR/$1.sops.txt") || die "cannot decrypt $DIR/$1.sops.txt with your sops key"
  [[ "$value" == "$PLACEHOLDER" ]] || printf '%s' "$value"
}

# collect VAR NAME "Prompt" REGEX: hidden entry, Enter keeps the repo's value, checked against REGEX.
collect() {
  local var="$1" name="$2" prompt="$3" regex="$4" input="" existing
  existing=$(current "$name")
  while :; do
    if [[ -n "$existing" ]]; then
      printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
    else
      printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    fi
    read -rs input || [[ -n "$input" ]] || die "no input"
    printf '\n'
    [[ -z "$input" && -n "$existing" ]] && input="$existing"
    [[ "$input" =~ $regex ]] && break
    warn "that does not look right; expected $5"
  done
  printf -v "$var" '%s' "$input"
}

# store NAME VALUE: JSON-encode VALUE and set it as the file's data, without a trailing newline.
store() {
  printf '%s' "$2" | jq -Rsc . | sops set --value-stdin "$DIR/$1.sops.txt" '["data"]'
  ok "wrote $DIR/$1.sops.txt"
}

cd "$(git rev-parse --show-toplevel)"

banner "nc8kg1101 monitoring: Page, Digest and Heartbeat credentials"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check prerequisites"
say "Checks this machine's tools and the checkout. Writes nothing yet."
for tool in git sops jq curl; do
  command -v "$tool" >/dev/null 2>&1 || die "$tool is not installed"
done
for name in pushover_user_key pushover_token discord_webhook watchdog_url; do
  [[ -f "$DIR/$name.sops.txt" ]] || die "no $DIR/$name.sops.txt; check out the branch that holds the monitoring Stack"
  sops -d "$DIR/$name.sops.txt" >/dev/null || die "cannot decrypt $DIR/$name.sops.txt with your sops key"
done
ok "your sops key decrypts all four files"
if [[ -z "$NO_PR" ]]; then
  command -v gh >/dev/null 2>&1 || die "gh is not installed"
  gh auth status >/dev/null 2>&1 || die "gh is not signed in (gh auth login)"
  [[ -z "$(git status --porcelain)" ]] || die "the checkout has uncommitted changes"
  git fetch -q origin
  # The PR goes to main once the monitoring Stack is there, else to its open PR's branch.
  if git cat-file -e "origin/main:$DIR/pushover_token.sops.txt" 2>/dev/null; then BASE=main; else BASE=302-monitoring; fi
  git switch -q -C "$BRANCH" "origin/$BASE"
  ok "on $BRANCH, from origin/$BASE"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Page: Pushover user key"
say "Critical alerts page your phone through Pushover (alertmanager/config.yml, receiver pushover)."
open_url "https://pushover.net/"
step "Sign in, or sign up and install the Pushover app on your phone (one-time licence after the trial)."
step "Copy 'Your User Key' from the top right of the dashboard (30 letters and digits)."
collect PUSHOVER_USER_KEY pushover_user_key "Paste the user key:" '^[A-Za-z0-9]{30}$' "30 letters and digits"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Page: Pushover application token"
say "Alertmanager sends as its own Pushover application, so you can mute or revoke it alone."
open_url "https://pushover.net/apps/build"
step "Name: nc8kg1101 Alertmanager. Type: Application. Tick the terms, then Create Application."
step "Copy its 'API Token/Key' (30 letters and digits)."
collect PUSHOVER_TOKEN pushover_token "Paste the API token:" '^[A-Za-z0-9]{30}$' "30 letters and digits"
if [[ -z "$NO_PR" ]]; then
  # Validates the pair without sending anything; the values go in on stdin, never in argv.
  if printf 'token=%s&user=%s' "$PUSHOVER_TOKEN" "$PUSHOVER_USER_KEY" \
      | curl -fsS -d @- https://api.pushover.net/1/users/validate.json >/dev/null 2>&1; then
    ok "Pushover accepts the token and user key"
  else
    die "Pushover rejected the token or user key; re-run and paste them again"
  fi
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Digest: Discord webhook"
say "Critical and Warning alerts go to a Discord channel, grouped per Stack (receiver discord)."
say "The repo holds the webhook the legacy monitoring group used. Give the Digest its own channel:"
step "In Discord, create a text channel for this Host's alerts, e.g. #nc8kg1101-alerts."
step "Channel → Edit Channel → Integrations → Webhooks → New Webhook → name it nc8kg1101 Alertmanager."
step "Copy Webhook URL."
collect DISCORD_WEBHOOK discord_webhook "Paste the webhook URL:" '^https://(discord|discordapp)\.com/api/webhooks/[0-9]+/[A-Za-z0-9_-]+$' \
  "https://discord.com/api/webhooks/<id>/<token>"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Heartbeat: healthchecks.io check"
say "Alertmanager pings this check every minute (the always-firing Watchdog alert)."
say "healthchecks.io alerts you when the pings stop: Prometheus, Alertmanager or the Host is down."
say "The repo holds the legacy group's check; Enter keeps it."
open_url "https://healthchecks.io/projects/"
step "Open your project → Add Check. Name: nc8kg1101 Alertmanager heartbeat."
step "Edit its schedule: Period 1 minute, Grace Time 5 minutes."
step "Under Integrations, make sure it notifies you (Pushover, email or both), not only Discord."
step "Copy its ping URL (https://hc-ping.com/<uuid>)."
collect WATCHDOG_URL watchdog_url "Paste the ping URL:" '^https://hc-ping\.com/[A-Za-z0-9/_-]+$' "https://hc-ping.com/<uuid>"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Write the SOPS files and open the PR"
store pushover_user_key "$PUSHOVER_USER_KEY"
store pushover_token "$PUSHOVER_TOKEN"
store discord_webhook "$DISCORD_WEBHOOK"
store watchdog_url "$WATCHDOG_URL"
if [[ -z "$NO_PR" ]]; then
  if confirm "Post a test message to the Digest channel now?"; then
    if printf 'url = "%s"\n' "$DISCORD_WEBHOOK" \
        | curl -fsS -K - -H 'Content-Type: application/json' \
            -d '{"content":"nc8kg1101 Alertmanager: Digest webhook test from scripts/monitoring-secrets.sh"}' >/dev/null; then
      ok "posted; check the channel"
    else
      warn "Discord rejected the webhook; check it before merging"
    fi
  fi
fi
unset PUSHOVER_USER_KEY PUSHOVER_TOKEN DISCORD_WEBHOOK WATCHDOG_URL
if [[ -z "$NO_PR" ]]; then
  if git diff --quiet -- "$DIR"; then
    ok "nothing changed; no PR needed"
  else
    git commit -q -m "Set nc8kg1101 monitoring's notification credentials (#302)" -- "$DIR"/*.sops.txt
    git push -q -u origin "$BRANCH"
    gh pr create -R "$REPO" --head "$BRANCH" --base "$BASE" \
      --title "Set nc8kg1101 monitoring's notification credentials" \
      --body "Pushover (Page), Discord (Digest) and healthchecks.io (Heartbeat) credentials for the monitoring Stack, from \`scripts/monitoring-secrets.sh\`. Refs #302."
    ok "opened the PR into $BASE; merge it before the cutover"
  fi
else
  note "WIZARD_NO_PR set: files written, nothing committed"
fi

finish
